from pathlib import Path
import re
p=Path('catalogo.html')
s=p.read_text(encoding='utf-8')

def once(old,new,label):
    global s
    n=s.count(old)
    if n!=1: raise SystemExit(f'{label}: expected 1 found {n}')
    s=s.replace(old,new,1)

once('<meta name="color-scheme" content="dark"><title>Catálogo · Nuvora</title>', '<meta name="color-scheme" content="dark"><meta property="og:type" content="website"><meta property="og:title" content="Catálogo Nuvora"><meta property="og:description" content="Productos, precios y disponibilidad actualizados desde Nuvora."><meta property="og:image" content="https://nuvora-ve.github.io/logo_512.png"><meta name="twitter:card" content="summary_large_image"><title>Catálogo · Nuvora</title>', 'social meta')
css='''.gallery-count{position:absolute;right:10px;top:10px;padding:6px 8px;border-radius:999px;background:rgba(3,9,20,.76);border:1px solid rgba(255,255,255,.12);font-size:9px;font-weight:900;color:#fff}.bs-price{margin-top:3px;color:#a9bed2;font-size:11px;font-weight:750}.detailbtn{width:100%;min-height:38px;margin:9px 0 0;border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.035);color:#dbe9f7;font-weight:850;cursor:pointer}.product-modal{position:fixed;z-index:42;inset:0;display:none;place-items:center;padding:18px;background:rgba(0,0,0,.78);backdrop-filter:blur(8px)}.product-modal.show{display:grid}.product-panel{width:min(620px,100%);max-height:92vh;overflow:auto;border:1px solid rgba(255,255,255,.13);border-radius:26px;background:#071426;box-shadow:0 28px 90px rgba(0,0,0,.7);padding:14px}.product-close{float:right;width:38px;height:38px;border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.04);color:#fff;font-size:21px}.gallery{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;gap:8px;clear:both;margin-top:8px}.gallery img,.gallery .ph{flex:0 0 100%;width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:18px;scroll-snap-align:start}.gallery-dots{text-align:center;color:var(--muted);font-size:11px;margin:7px 0}.product-info{padding:5px 5px 8px}.product-info h2{margin:8px 0 5px;font-size:24px}.product-info .price{font-size:22px}.share-product{width:100%;min-height:42px;margin-top:10px;border:1px solid rgba(49,216,255,.3);border-radius:13px;background:rgba(49,216,255,.07);color:#8cecff;font-weight:900}'''
once('</style></head>',css+'</style></head>','gallery css')
modal='''<div id="productModal" class="product-modal" role="dialog" aria-modal="true" aria-label="Detalle del producto"><div class="product-panel"><button id="productClose" class="product-close" aria-label="Cerrar">×</button><div id="productDetail"></div></div></div>'''
once('<div id="toast" class="toast" role="status">Agregado al pedido</div>', '<div id="toast" class="toast" role="status">Agregado al pedido</div>'+modal,'product modal')
# Context carries BCV rate.
s=s.replace("let ctx={name:'Negocio',digits:'',currency:'$',products:[]};","let ctx={name:'Negocio',digits:'',currency:'$',rate:0,products:[]};",1)
# Normalize old and new payloads, preserving legacy single image.
pat=re.compile(r"const norm=\(p,i\)=>\{.*?\};const showToast=",re.S)
m=pat.search(s)
if not m: raise SystemExit('norm function missing')
norm="""const norm=(p,i)=>{if(Array.isArray(p)){const one=p[3]||'';return{id:String(p[5]||i),name:p[0]||'',price:p[1]||'',detail:p[2]||'',photo:one,photos:one?[one]:[],stock:Number(p[4]??999999),amount:Number(p[6]??NaN),currency:p[7]||'',bs:NaN}}const live=('nombre'in p)||('precio'in p)||('foto_url'in p);if(live){const photos=Array.isArray(p.fotos)?p.fotos.filter(Boolean):Array.isArray(p.photoUrls)?p.photoUrls.filter(Boolean):[];const one=p.foto_url||p.photoUrl||'';if(one&&!photos.includes(one))photos.unshift(one);return{id:String(p.id||i),name:p.nombre||'',price:'',detail:p.descripcion||'',photo:photos[0]||one,photos,stock:Number(p.stock??0),amount:Number(p.precio??0),currency:p.moneda||'',bs:Number(p.precio_bs??NaN)}}const photos=Array.isArray(p.photos)?p.photos.filter(Boolean):[];const one=p.photo||'';if(one&&!photos.includes(one))photos.unshift(one);return{id:String(p.id||i),name:p.name||'',price:p.price||'',detail:p.detail||'',photo:photos[0]||one,photos,stock:Number(p.stock??999999),amount:Number(p.amount??NaN),currency:p.currency||'',bs:Number(p.bs??NaN)}};const showToast="""
s=s[:m.start()]+norm+s[m.end():]
# Inject product detail helpers before render.
marker='function render(name,products,meta={}){'
idx=s.find(marker)
if idx<0: raise SystemExit('render marker missing')
helpers="""const productModal=document.getElementById('productModal'),productDetail=document.getElementById('productDetail');function closeProduct(){productModal.classList.remove('show');if(location.hash.includes('&p='))history.replaceState(null,'',location.href.replace(/&p=[^&]*/,''))}document.getElementById('productClose').onclick=closeProduct;productModal.onclick=e=>{if(e.target===productModal)closeProduct()};function openProduct(p,updateHash=true){if(!p)return;const photos=(p.photos&&p.photos.length?p.photos:(p.photo?[p.photo]:[]));const imgs=photos.length?photos.map(u=>`<img src="${esc(u)}" alt="${esc(p.name)}" loading="lazy">`).join(''):'<div class="ph">◇</div>';const bs=Number.isFinite(p.bs)?p.bs:(ctx.rate>0&&String(p.currency).toUpperCase()==='USD'?parseAmount(p)*ctx.rate:NaN);productDetail.innerHTML=`<div class="gallery">${imgs}</div>${photos.length>1?`<div class="gallery-dots">Desliza · ${photos.length} fotos</div>`:''}<div class="product-info"><h2>${esc(p.name)}</h2><div class="price">${esc(p.price||money(parseAmount(p)))}</div>${Number.isFinite(bs)?`<div class="bs-price">Ref. BCV: Bs ${bs.toLocaleString('es-VE',{minimumFractionDigits:2,maximumFractionDigits:2})}</div>`:''}${p.detail?`<p class="detail">${esc(p.detail)}</p>`:''}<div class="stock ${p.stock<=0?'out':''}">${p.stock<=0?'Agotado':`${Math.floor(p.stock)} en existencia`}</div><button class="share-product" id="shareProduct">Compartir este producto</button></div>`;productModal.classList.add('show');if(updateHash&&location.hash.includes('c=')){const base=location.hash.replace(/&p=[^&]*/,'');history.replaceState(null,'',location.pathname+location.search+base+'&p='+encodeURIComponent(p.id))}document.getElementById('shareProduct').onclick=async()=>{const url=location.href,title=p.name;if(navigator.share){try{await navigator.share({title,text:`${p.name} · ${p.price||money(parseAmount(p))}`,url});return}catch(_){}}try{await navigator.clipboard.writeText(url);showToast()}catch(_){}}}function render(name,products,meta={}){"""
s=s[:idx]+helpers+s[idx+len(marker):]
# Replace render body until completarFotos.
start=s.find('function render(name,products,meta={}){')
end=s.find('async function completarFotos',start)
if start<0 or end<0: raise SystemExit('render range missing')
render="""function render(name,products,meta={}){const logo=meta.logo||'',desc=meta.description||'Productos, precios y disponibilidad actualizados desde Nuvora.',digits=String(meta.whatsapp||'').replace(/\D/g,'');ctx={name:name||'Negocio',digits,currency:meta.currency||'',rate:Number(meta.rate||0),products:products.map(norm)};if(!ctx.currency){const first=ctx.products[0];ctx.currency=first?.currency||String(first?.price||'').trim().split(/\s+/)[0]||'$'}const cards=ctx.products.map(p=>{const amount=parseAmount(p),stock=Number.isFinite(p.stock)?p.stock:999999,max=Math.max(0,Math.floor(stock)),out=max<=0,photos=p.photos&&p.photos.length?p.photos:(p.photo?[p.photo]:[]),cover=photos[0]||'',bs=Number.isFinite(p.bs)?p.bs:(ctx.rate>0&&String(p.currency).toUpperCase()==='USD'?amount*ctx.rate:NaN),visual=cover?`<div class="visual"><img class="photo" src="${esc(cover)}" alt="${esc(p.name)}" loading="lazy" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'"><div class="ph" style="display:none">◇</div><span class="badge">${out?'AGOTADO':'DISPONIBLE'}</span>${photos.length>1?`<span class="gallery-count">▣ ${photos.length}</span>`:''}</div>`:`<div class="visual"><div class="ph">◇</div><span class="badge">${out?'AGOTADO':'DISPONIBLE'}</span></div>`;return`<article class="item" data-name="${esc(p.name.toLowerCase())}">${visual}<div class="body"><div class="name">${esc(p.name)}</div><div class="price">${esc(p.price||money(amount))}</div>${Number.isFinite(bs)?`<div class="bs-price">Ref. BCV: Bs ${bs.toLocaleString('es-VE',{minimumFractionDigits:2,maximumFractionDigits:2})}</div>`:''}${p.detail?`<div class="detail">${esc(p.detail)}</div>`:''}<div class="stock ${out?'out':''}">${out?'Sin stock':(stock<999999?`${Math.floor(stock)} en existencia`:'En existencia')}</div><button class="detailbtn" data-detail="${esc(p.id)}">Ver detalle${photos.length>1?' y fotos':''}</button><button class="add" data-add="${esc(p.id)}" ${out?'disabled':''}>${out?'Agotado':'Agregar al pedido'}</button></div></article>`}).join('');const mark=logo?`<img class="logo" src="${esc(logo)}" alt="${esc(name||'Negocio')}" onerror="this.outerHTML='<div class=\\'initial\\'>${esc((name||'N').trim().charAt(0).toUpperCase()||'N')}</div>'">`:`<div class="initial">${esc((name||'N').trim().charAt(0).toUpperCase()||'N')}</div>`;root.innerHTML=`<section class="hero"><div class="hero-main">${mark}<div class="hero-copy"><div class="eyebrow">TIENDA · CATÁLOGO DIGITAL</div><h1>${esc(name||'Negocio')}</h1><p class="sub">${esc(desc)}</p></div></div><div class="hero-actions">${digits?`<a class="contact" target="_blank" rel="noopener" href="https://wa.me/${esc(digits)}">WhatsApp del negocio</a>`:''}<span class="trust">Disponibilidad sincronizada con Nuvora</span></div></section><div class="toolbar"><div class="search"><input id="searchProducts" type="search" placeholder="Buscar productos…" aria-label="Buscar productos"></div><span class="count" id="visibleCount">${ctx.products.length} productos</span></div><div class="section-head"><h2>Productos</h2><span>Elige y arma tu pedido</span></div><div class="grid" id="productGrid">${cards||'<div class="empty" style="grid-column:1/-1">Este catálogo todavía no tiene productos disponibles.</div>'}</div><a class="cta" href="https://nuvora-ve.github.io/">Impulsa tu negocio con Nuvora</a><div class="foot">Catálogo impulsado por Nuvora · Tu dinero y tu negocio bajo control</div>`;root.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const id=b.getAttribute('data-add'),p=ctx.products.find(x=>x.id===id);if(!p)return;const max=Math.max(0,Math.floor(Number.isFinite(p.stock)?p.stock:999999)),q=cart.get(id)||0;if(q<max){cart.set(id,q+1);updateCart();showToast()}});root.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openProduct(ctx.products.find(x=>x.id===b.getAttribute('data-detail'))));const search=document.getElementById('searchProducts');search?.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();let visible=0;root.querySelectorAll('.item').forEach(card=>{const on=!q||card.dataset.name.includes(q);card.style.display=on?'':'none';if(on)visible++});document.getElementById('visibleCount').textContent=`${visible} ${visible===1?'producto':'productos'}`});updateCart();const requested=location.hash.match(/(?:^#|&)p=([^&]+)/);if(requested){const p=ctx.products.find(x=>x.id===decodeURIComponent(requested[1]));if(p)setTimeout(()=>openProduct(p,false),0)}}async function completarFotos"""
s=s[:start]+render+s[end+len('async function completarFotos'):]
# Live snapshot receives rate.
once("render(data.nombre,Array.isArray(data.productos)?data.productos:[],{logo:data.logo||data.logo_url||'',description:data.descripcion||'',whatsapp:data.whatsapp||'',currency:data.moneda||''});return", "render(data.nombre,Array.isArray(data.productos)?data.productos:[],{logo:data.logo||data.logo_url||'',description:data.descripcion||'',whatsapp:data.whatsapp||'',currency:data.moneda||'',rate:data.tasa_bcv||0});return", 'live rate')
# Minimal assertions.
for needle in ['p.fotos','gallery-count','precio_bs','data.tasa_bcv','shareProduct','og:image']:
    if needle not in s: raise SystemExit('missing '+needle)
p.write_text(s,encoding='utf-8')
print('catalogo.html upgraded for Nuvora 7.6')
